      review_status: 'pending',
      extraction_summary: {
        paper_bundle: bundle,
        extraction_response_id: state.extraction_response_id,
        ready_for_approval: readyForApproval,
        manual_review_required: true,
        independent_paid_verifier_used: false,
        api_usage: state.api_usage,
